import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';
import './ProfilePage.css';

const ProfilePage = () => {
  const { user, updateUserBalance } = useAuth();
  const navigate = useNavigate();
  const [profile, setProfile] = useState(null);
  const [ownedGames, setOwnedGames] = useState([]);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('profile');

  useEffect(() => {
    if (!user) {
      navigate('/login');
      return;
    }
    loadProfile();
    loadOwnedGames();
  }, [user, navigate]);

  const loadProfile = async () => {
    try {
      const response = await api.get('/users/profile');
      setProfile(response.data);
      updateUserBalance(response.data.balance);
    } catch (error) {
      console.error('Ошибка загрузки профиля:', error);
    } finally {
      setLoading(false);
    }
  };

  const loadOwnedGames = async () => {
    try {
      const response = await api.get('/users/profile/games');
      setOwnedGames(response.data);
    } catch (error) {
      console.error('Ошибка загрузки игр:', error);
    }
  };

  if (loading) {
    return (
      <div className="profile-page">
        <div className="loading-container">
          <div className="spinner"></div>
          <p>Загрузка профиля...</p>
        </div>
      </div>
    );
  }

  if (!profile) {
    return (
      <div className="profile-page">
        <div className="error-container">
          <p>❌ Ошибка загрузки профиля</p>
          <button onClick={() => navigate('/')} className="btn-home">
            На главную
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="profile-page">
      <div className="profile-container">
        {/* Шапка профиля */}
        <div className="profile-header">
          <div className="profile-avatar-section">
            <div className="profile-avatar-large">
              {profile.avatar ? (
                <img src={profile.avatar} alt={profile.username} />
              ) : (
                <div className="avatar-placeholder">
                  {profile.username.charAt(0).toUpperCase()}
                </div>
              )}
            </div>
            <button className="btn-change-avatar">
              📷 Изменить аватар
            </button>
          </div>
          
          <div className="profile-info-section">
            <h1 className="profile-username">{profile.username}</h1>
            <p className="profile-email">📧 {profile.email}</p>
            <p className="profile-member-since">
              📅 На сайте с {new Date(profile.createdAt).toLocaleDateString('ru-RU', {
                day: 'numeric',
                month: 'long',
                year: 'numeric'
              })}
            </p>
          </div>

          <div className="profile-balance-section">
            <div className="balance-card">
              <span className="balance-label">💰 Баланс</span>
              <span className="balance-value">{profile.balance.toFixed(2)} ₽</span>
            </div>
            <button 
              className="btn-topup"
              onClick={() => navigate('/topup')}
            >
              ➕ Пополнить
            </button>
          </div>
        </div>

        {/* Вкладки */}
        <div className="profile-tabs">
          <button 
            className={`tab-btn ${activeTab === 'profile' ? 'active' : ''}`}
            onClick={() => setActiveTab('profile')}
          >
            👤 Профиль
          </button>
          <button 
            className={`tab-btn ${activeTab === 'games' ? 'active' : ''}`}
            onClick={() => setActiveTab('games')}
          >
             Библиотека ({ownedGames.length})
          </button>
          <button 
            className={`tab-btn ${activeTab === 'stats' ? 'active' : ''}`}
            onClick={() => setActiveTab('stats')}
          >
            📊 Статистика
          </button>
        </div>

        {/* Контент вкладок */}
        <div className="profile-content">
          {activeTab === 'profile' && (
            <div className="tab-content profile-tab">
              <h2>📋 Информация о профиле</h2>
              <div className="info-grid">
                <div className="info-item">
                  <label>ID пользователя</label>
                  <span>#{profile.id}</span>
                </div>
                <div className="info-item">
                  <label>Имя пользователя</label>
                  <span>{profile.username}</span>
                </div>
                <div className="info-item">
                  <label>Email</label>
                  <span>{profile.email}</span>
                </div>
                <div className="info-item">
                  <label>Баланс</label>
                  <span className="balance-highlight">{profile.balance.toFixed(2)} ₽</span>
                </div>
                <div className="info-item">
                  <label>Дата регистрации</label>
                  <span>{new Date(profile.createdAt).toLocaleDateString('ru-RU')}</span>
                </div>
                <div className="info-item">
                  <label>Статус</label>
                  <span className="status-online">🟢 Активен</span>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'games' && (
            <div className="tab-content games-tab">
              <h2>📚 Моя библиотека игр</h2>
              {ownedGames.length > 0 ? (
                <div className="games-grid">
                  {ownedGames.map(game => (
                    <div key={game.id} className="game-card">
                      <div className="game-card-image">
                        <img src={game.imageUrl || 'https://via.placeholder.com/300x200?text=No+Image'} alt={game.title} />
                      </div>
                      <div className="game-card-info">
                        <h3>{game.title}</h3>
                        <p className="game-genre">{game.genre}</p>
                        <p className="game-price">{game.price.toFixed(2)} ₽</p>
                        <p className="game-purchased">
                          📅 Куплена: {new Date(game.purchasedAt).toLocaleDateString('ru-RU')}
                        </p>
                        <button className="btn-play">
                          🎮 Играть
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="no-games">
                  <div className="no-games-icon">🎮</div>
                  <h3>У вас пока нет игр</h3>
                  <p>Посетите магазин, чтобы приобрести игры</p>
                  <button 
                    className="btn-go-store"
                    onClick={() => navigate('/store')}
                  >
                    🛒 Перейти в магазин
                  </button>
                </div>
              )}
            </div>
          )}

          {activeTab === 'stats' && (
            <div className="tab-content stats-tab">
              <h2>📊 Статистика</h2>
              <div className="stats-grid">
                <div className="stat-card">
                  <div className="stat-icon">💰</div>
                  <div className="stat-value">{profile.totalSpent.toFixed(2)} ₽</div>
                  <div className="stat-label">Всего потрачено</div>
                </div>
                <div className="stat-card">
                  <div className="stat-icon">📚</div>
                  <div className="stat-value">{ownedGames.length}</div>
                  <div className="stat-label">Игр в библиотеке</div>
                </div>
                <div className="stat-card">
                  <div className="stat-icon">📅</div>
                  <div className="stat-value">
                    {Math.floor((new Date() - new Date(profile.createdAt)) / (1000 * 60 * 60 * 24))}
                  </div>
                  <div className="stat-label">Дней на сайте</div>
                </div>
                <div className="stat-card">
                  <div className="stat-icon">🎯</div>
                  <div className="stat-value">
                    {profile.ownedGamesCount > 0 ? 'Active' : 'New'}
                  </div>
                  <div className="stat-label">Статус</div>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default ProfilePage;
